SELECT analytics_order_facts.region, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year IN (2026, 2022) AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.payment_method = 'invoice' GROUP BY analytics_order_facts.region ORDER BY analytics_order_facts.region ASC LIMIT 24
